p = 61
N = {}
for a in range(p):
    for b in range(p):
        k = (a*a + b*b) % p
        if k not in N:
            N[k] = 0
        N[k] += 1

# Print the results in a structured way
print("Distribution of a^2 + b^2 mod 61:")
for k in range(p):
    print(f"k={k}: N_{k} = {N.get(k, 0)}")

# Check the total sum
total = sum(N.values())
print(f"\nTotal count: {total}")

